import java.io.*;import java.util.*;import java.lang.reflect.*;
import com.android.tools.smali.dexlib2.*;import com.android.tools.smali.dexlib2.iface.*;import com.android.tools.smali.dexlib2.iface.instruction.*;
public class VerifyClawPatch {
 static void require(boolean b,String s){if(!b)throw new AssertionError(s);}
 static void methods(Class<?> c,Map<String,java.lang.reflect.Method> out){for(Class<?> i:c.getInterfaces()){for(java.lang.reflect.Method m:i.getMethods())if(m.getParameterCount()==0&&m.getName().startsWith("get"))out.put(m.getName(),m);methods(i,out);}if(c.getSuperclass()!=null)methods(c.getSuperclass(),out);}
 static String fingerprint(Instruction ins)throws Exception{Map<String,java.lang.reflect.Method> getters=new TreeMap<>();methods(ins.getClass(),getters);StringBuilder out=new StringBuilder();for(Map.Entry<String,java.lang.reflect.Method> e:getters.entrySet()){Object v=e.getValue().invoke(ins);out.append(e.getKey()).append('=');if(v instanceof Iterable){for(Object item:(Iterable<?>)v){if(item instanceof SwitchElement){SwitchElement x=(SwitchElement)item;out.append(x.getKey()).append(':').append(x.getOffset());}else out.append(item);out.append(',');}}else out.append(v);out.append(';');}return out.toString();}
 static List<Instruction> list(MethodImplementation code){List<Instruction> out=new ArrayList<>();if(code!=null)for(Instruction i:code.getInstructions())out.add(i);return out;}
 static String key(com.android.tools.smali.dexlib2.iface.Method m){return m.getDefiningClass()+"->"+m.getName()+m.getParameterTypes()+m.getReturnType();}
 public static void main(String[] args)throws Exception{
 DexFile old=DexFileFactory.loadDexFile(new File(args[0]),Opcodes.forApi(26)),updated=DexFileFactory.loadDexFile(new File(args[1]),Opcodes.forApi(26));Map<String,com.android.tools.smali.dexlib2.iface.Method> defs=new HashMap<>();Set<String> classes=new HashSet<>();for(ClassDef c:updated.getClasses()){classes.add(c.getType());for(com.android.tools.smali.dexlib2.iface.Method m:c.getMethods())defs.put(key(m),m);}int count=0,patch=0;
 for(ClassDef c:old.getClasses()){require(classes.remove(c.getType()),"Missing old class");for(com.android.tools.smali.dexlib2.iface.Method m:c.getMethods()){com.android.tools.smali.dexlib2.iface.Method n=defs.remove(key(m));require(n!=null,"Missing method "+key(m));require(m.getAccessFlags()==n.getAccessFlags(),"Access flags changed");if(m.getImplementation()==null){require(n.getImplementation()==null,"Added implementation");continue;}
 List<Instruction> before=list(m.getImplementation()),after=list(n.getImplementation());int skip=0;if(c.getType().equals("Lcom/guocheng/mediapocket/Net;")&&m.getName().equals("bytes")){skip=6;patch++;Opcode[] ops={Opcode.INVOKE_STATIC_RANGE,Opcode.MOVE_RESULT,Opcode.IF_EQZ,Opcode.INVOKE_STATIC_RANGE,Opcode.MOVE_RESULT_OBJECT,Opcode.RETURN_OBJECT};int total=0,branchAt=0;for(int i=0;i<6;i++){require(after.get(i).getOpcode()==ops[i],"Guard instruction changed");if(i==2)branchAt=total;total+=after.get(i).getCodeUnits();}require(((OffsetInstruction)after.get(2)).getCodeOffset()==total-branchAt,"Guard must branch to original fallback");require(m.getImplementation().getRegisterCount()==n.getImplementation().getRegisterCount(),"Register count changed");}
 require(after.size()==before.size()+skip,"Original method instructions changed "+key(m));for(int i=0;i<before.size();i++)require(fingerprint(before.get(i)).equals(fingerprint(after.get(i+skip))),"Original instruction changed "+key(m)+" at "+i);count++;
 }}require(classes.isEmpty()&&defs.isEmpty(),"Unexpected original DEX definitions");require(patch==1,"Exactly one guard expected");System.out.println("PASS: "+count+" original method implementations preserved; only Net.bytes has a 6-instruction host guard with verified fallback branch.");
 }
}
